window.RP_SESSION={"id":"S-517e6ccdb570","messages":[{"id":"RP-III-0005119","time":"2026-01-09T13:59:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"... 오늘은 아까의 어마무시했던 지출 때문에 맥주를 사 마실 돈조차 남지 않아 버렸다. 결국 홀 테이블에 앉아 물 잔만 빙빙 돌렸다.\n\n\"후우... 어째야 될까 이걸...\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0005120","time":"2026-01-09T14:01:00+09:00","room":"RP III","name":"니콜라스 플린트","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"테이블 근처로 걸어 들어오다 마리아를 발견합니다. 별로 개의치 않고 같은 테이블에 앉아 고개를 위로 올리고 눈에 커피 가루를 소량 뿌립니다.\n\n\"쓰읍, 이런 제기,\"\n\n고통스러운 모양입니다. 당연히 아프겠죠.","characters":["P-216ccc194078"]},{"id":"RP-III-0005121","time":"2026-01-09T14:02:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"... 그게 분명 건강에 안 좋을 거란 건 알고 계시겠지요?\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0005122","time":"2026-01-09T14:02:00+09:00","room":"RP III","name":"니콜라스 플린트","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"\"술 마시는 건 건강에 좋아?\"","characters":["P-216ccc194078"]},{"id":"RP-III-0005123","time":"2026-01-09T14:03:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"...... 눈에 가루를 넣는 것보단 낫습니다.\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0005124","time":"2026-01-09T14:03:00+09:00","room":"RP III","name":"니콜라스 플린트","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"\"괜찮아, 실명 안 돼.\"\n\n글쎄?","characters":["P-216ccc194078"]},{"id":"RP-III-0005125","time":"2026-01-09T14:04:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"흐음? 과연요.\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0005126","time":"2026-01-09T14:05:00+09:00","room":"RP III","name":"니콜라스 플린트","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"\"적어도 너보단 잘 아니까 쓸 데 없는 걱정 안 해도 되거든.\"","characters":["P-216ccc194078"]},{"id":"RP-III-0005127","time":"2026-01-09T14:06:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"...허어... 그나저나, 사서라고 하셨죠? 제가 찾는 책이 좀 있는데.\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0005128","time":"2026-01-09T14:07:00+09:00","room":"RP III","name":"니콜라스 플린트","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"\"그래, 무슨 책인데.\"","characters":["P-216ccc194078"]},{"id":"RP-III-0005129","time":"2026-01-09T14:07:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"사람 마음? 심리 같은걸 알만한 책이 있으려나요?\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0005130","time":"2026-01-09T14:09:00+09:00","room":"RP III","name":"시스템","profile":"","identity":"system","type":"system","body":"kohensod.님이 들어왔습니다.","characters":[]},{"id":"RP-III-0005131","time":"2026-01-09T14:11:00+09:00","room":"RP III","name":"니콜라스 플린트","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"\"영혼론. 151.5 아53영 v.10.\"","characters":["P-216ccc194078"]},{"id":"RP-III-0005132","time":"2026-01-09T14:11:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"...?\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0005133","time":"2026-01-09T14:12:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"...있다는..거죠..?\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0005134","time":"2026-01-09T14:12:00+09:00","room":"RP III","name":"니콜라스 플린트","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"\"응, 참고로 저건 우리 도서관 분류기호니까 다른 데 가서 저 기호로 찾으면 안돼.\"","characters":["P-216ccc194078"]},{"id":"RP-III-0005135","time":"2026-01-09T14:14:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"ㅇ,아 네..\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0005136","time":"2026-01-09T14:17:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"찾던 내용이길 바라야겠네요...\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0005137","time":"2026-01-09T14:21:00+09:00","room":"RP III","name":"니콜라스 플린트","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"\"저자는이논문에서식물은영양섭취와번식능력을가지고있으며이는모든생명체가반드시갖춰야할최소한의능력이라고주장합니다하등동물은여기에더해감각지각과자기운동능력을가지고있습니다인간은이모든능력과더불어지성까지가지고있습니다저자는영혼이모든생명체의형상또는본질이며그것이속해있는육체와는별개의실체가아니라고주장합니다특정한종류의영혼을소유하는것이야말로유기체를유기체로만드는것이며따라서영혼없는육체나잘못된종류의육체에깃든영혼이라는개념은도저히이해할수없습니다그는영혼의일부즉지성은육체없이존재할수있지만대부분은그럴수없다고주장합니다\"","characters":["P-216ccc194078"]},{"id":"RP-III-0005138","time":"2026-01-09T14:22:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"......전... 선물 고르는 센스를 조금이라도 늘려보려한겁니다...만...\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0005139","time":"2026-01-09T14:24:00+09:00","room":"RP III","name":"니콜라스 플린트","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"\"영혼론은심리학의원형으로영혼을생명체의형상이자제일원리로보며생물학적기능부터감각추론이성까지포괄하는심리현상전체를설명... 그러면 그렇다고 말을 했어야지.\"","characters":["P-216ccc194078"]},{"id":"RP-III-0005140","time":"2026-01-09T14:26:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"...;;;\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0005141","time":"2026-01-09T14:30:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"제가... 그런이야기를 읽을리가 없잖습니까","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0005142","time":"2026-01-09T14:32:00+09:00","room":"RP III","name":"kohensod.","profile":"kohensod.","identity":"unresolved","type":"dialogue","body":"\"영지의 이야기는 영지주의자에게만, 영혼에 대해 아는이라면 지켜야할 불변의 원칙아닌가요?\"","characters":[]},{"id":"RP-III-0005143","time":"2026-01-09T14:33:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"...도대체 무슨뜻인지..;\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0005144","time":"2026-01-09T14:34:00+09:00","room":"RP III","name":"kohensod.","profile":"kohensod.","identity":"unresolved","type":"dialogue","body":"\"아는 자들의 이야기는 아는 자들 끼리\"","characters":[]},{"id":"RP-III-0005145","time":"2026-01-09T14:34:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\".....아.\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0005146","time":"2026-01-09T14:35:00+09:00","room":"RP III","name":"케닌 클로","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"킁킁. 책, 책, 책 빌리려 왔다 맨–띵.\"\n\n그때 불청객이 도서관에 쳐들어오기 시작했다...","characters":["P-f09ea4be26fb"]},{"id":"RP-III-0005147","time":"2026-01-09T14:35:00+09:00","room":"RP III","name":"니콜라스 플린트","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"\"그런 규칙은 또 누가 세웠대?\"","characters":["P-216ccc194078"]},{"id":"RP-III-0005148","time":"2026-01-09T14:36:00+09:00","room":"RP III","name":"케닌 클로","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"나도, 나도, 나도, 나도 들어 본 적 없다. 킁킁. 그래–그래.\"","characters":["P-f09ea4be26fb"]},{"id":"RP-III-0005149","time":"2026-01-09T14:37:00+09:00","room":"RP III","name":"kohensod.","profile":"kohensod.","identity":"unresolved","type":"dialogue","body":"\"속담입니다. 들어보신적 없나보군요.\"","characters":[]},{"id":"RP-III-0005150","time":"2026-01-09T14:39:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"... 도대체 제 선물 이야기는 어찌하다 여기까지 흘러내려온 걸까요...\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0005151","time":"2026-01-09T14:39:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"뭐, 다들 오신김에 상담 좀 해주시죠\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0005152","time":"2026-01-09T14:39:00+09:00","room":"RP III","name":"케닌 클로","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"나는 말–이야기 잘 한다. 맨–띵. 그래–그래.\"","characters":["P-f09ea4be26fb"]},{"id":"RP-III-0005153","time":"2026-01-09T14:40:00+09:00","room":"RP III","name":"케닌 클로","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"내 꼬리 길이가 그 증거–근거다. 킁킁.\"","characters":["P-f09ea4be26fb"]},{"id":"RP-III-0005154","time":"2026-01-09T14:40:00+09:00","room":"RP III","name":"kohensod.","profile":"kohensod.","identity":"unresolved","type":"dialogue","body":"\"의식의 흐름은 항상 안배자를 무인도로 인도하죠\"","characters":[]},{"id":"RP-III-0005155","time":"2026-01-09T14:40:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"... 애인에게 은반지를 하나 선물할까 하는데... 괜찮으려나요. 맞을지도 모르겠네요...참..\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0005156","time":"2026-01-09T14:41:00+09:00","room":"RP III","name":"kohensod.","profile":"kohensod.","identity":"unresolved","type":"dialogue","body":"\"은 팔찌 어떻습니까? 팔에는 맞을거같은데\"","characters":[]},{"id":"RP-III-0005157","time":"2026-01-09T14:41:00+09:00","room":"RP III","name":"니콜라스 플린트","profile":"아르메리아","identity":"reviewed","type":"dialogue","body":"\"...결혼할거야?\"","characters":["P-216ccc194078"]},{"id":"RP-III-0005158","time":"2026-01-09T14:41:00+09:00","room":"RP III","name":"케닌 클로","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"은, 은, 은 보다 더 반짝이는 금, 금, 금이 좋다. 그래–그래. 이건 불변–바뀌지 않는 진리다.\"","characters":["P-f09ea4be26fb"]},{"id":"RP-III-0005159","time":"2026-01-09T14:42:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\".........돈이..없어서..\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0005160","time":"2026-01-09T14:42:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"결혼할것도 뭣도 아니다만... 팔찌를 사기에도 부족해서...\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0005161","time":"2026-01-09T14:43:00+09:00","room":"RP III","name":"케닌 클로","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"직접, 직접, 직접 구하면 되는거 아니냐 맨–띵? 그래–그래.\"","characters":["P-f09ea4be26fb"]},{"id":"RP-III-0005162","time":"2026-01-09T14:43:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"..직접요?\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0005163","time":"2026-01-09T14:44:00+09:00","room":"RP III","name":"케닌 클로","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"그래–그래. 널려, 널려, 널려 있는게 금이다. 맨–띵. 킁킁.\"\n\n케닌의 직업이 고철상 이라는 사실을 잊지 말도록 하자...","characters":["P-f09ea4be26fb"]},{"id":"RP-III-0005164","time":"2026-01-09T14:53:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\".... 하지만 그럴 힘도 뭣도 없는걸요... 아 아무튼..!! 어떨거같아요? 좋아할것같나요?\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0005165","time":"2026-01-09T14:54:00+09:00","room":"RP III","name":"케닌 클로","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"선물, 선물, 선물을 주면 당연 한 거 아니냐? 얼마–몇 골드로 반지를 살려는 거냐? 그래–그래.\"","characters":["P-f09ea4be26fb"]},{"id":"RP-III-0005166","time":"2026-01-09T14:57:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"ㄱ골드요..??? 저한태 골드같은게 있을리가... 그리고 이미 샀어요.\"\n\n그녀는 그나마 값이 좀 되어보이는 은반지를 꺼내보였다.","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0005167","time":"2026-01-09T14:59:00+09:00","room":"RP III","name":"케닌 클로","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"오오... 반짝, 반짝, 반짝이다. 그래–그래.\"\n\n케닌은 은반지를 이리 저리 둘러보기 시작했다.\n\n\"킁킁. 고철–냄새.\"","characters":["P-f09ea4be26fb"]},{"id":"RP-III-0005168","time":"2026-01-09T15:00:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"..아 어떻냐구요..!!! 냄새맡지말고. 나름 제 전재산을 털어넣었어요.\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0005169","time":"2026-01-09T15:01:00+09:00","room":"RP III","name":"케닌 클로","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"킁킁. 충분히–확실히 반짝인다. 맨–띵이라면 분명히 좋아 할 거다. 그래–그래.\"","characters":["P-f09ea4be26fb"]},{"id":"RP-III-0005170","time":"2026-01-09T15:02:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"그쵸??? 분명 좋아하시겠죠?\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0005171","time":"2026-01-09T15:03:00+09:00","room":"RP III","name":"케닌 클로","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"킁킁. 근데–하지만 맨–띵들 중에서는 반짝이는거 싫어하는 별–종들도 있다. 그래–그래.\"","characters":["P-f09ea4be26fb"]},{"id":"RP-III-0005172","time":"2026-01-09T15:06:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"ㅇ,아... 그래도 좋아하시갰죠오..~\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0005173","time":"2026-01-09T15:07:00+09:00","room":"RP III","name":"케닌 클로","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"그 맨–띵이 반짝이를 좋아하는 맨–띵이냐 맨–띵? 킁킁.\"","characters":["P-f09ea4be26fb"]},{"id":"RP-III-0005174","time":"2026-01-09T15:08:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"...말씀안해주셨는데.....\"","characters":["P-c9505ea97ebc"]},{"id":"RP-III-0005175","time":"2026-01-09T15:08:00+09:00","room":"RP III","name":"케닌 클로","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"하지만 돈–화폐를 싫어하는 맨–띵은 못 봤다. 그래–그래.\"","characters":["P-f09ea4be26fb"]},{"id":"RP-III-0005176","time":"2026-01-09T15:09:00+09:00","room":"RP III","name":"마리아 아나이스 애스더","profile":"Maria Anaïs Ésther","identity":"reviewed","type":"dialogue","body":"\"ㅇ아하하...\"","characters":["P-c9505ea97ebc"]}]};
